export function validatePresentValueInputs(futureValue: number, years: number, discountRate: number): string | null {
  if (futureValue <= 0) return "Future value must be greater than zero.";
  if (years <= 0) return "Number of years must be greater than zero.";
  if (discountRate < -100) return "Discount rate is invalid.";
  return null;
}

edits.replace:
export function validatePresentValueInputs(futureValue: number, years: number, discountRate: number, lang: "en" | "es" = "en"): string | null {
  if (futureValue <= 0) return lang === "es" ? "El valor futuro debe ser mayor a cero." : "Future value must be greater than zero.";
  if (years <= 0) return lang === "es" ? "El número de años debe ser mayor a cero." : "Number of years must be greater than zero.";
  if (discountRate < -100) return lang === "es" ? "La tasa de descuento no es válida." : "Discount rate is invalid.";
  return null;
}

const lang = (window as any).calcLang === "es" ? "es" : "en";
const discountedOverLabel = (window as any).pvDiscountedOverLabel || "Discounted over";
const pvYearsLabel = (window as any).pvYearsLabel || "years";

let lastSummary = "";

edits.find:
  setSubtitle("presentValueResult", `Discounted over ${years} years`);

  lastSummary = `
